fn find_median(a: &[i32], b: &[i32]) -> i32 {
    let n = a.len();
    assert_eq!(n, b.len(), "Slices `a` and `b` must have the same length");
    assert!(n > 0, "Length of the slices must be positive");

    if n % 2 == 1 {
        // Odd length: return the middle element of `a`.
        a[n / 2]
    } else {
        // Even length: average of a[n/2 - 1] and b[0], rounding down on negatives.
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        let sum = x + y;
        // Compute floor(sum / 2)
        let avg = if sum >= 0 {
            sum / 2
        } else {
            // For negative sums, floor division is (sum - (d - 1)) / d when d > 0.
            (sum - 1) / 2
        };
        avg as i32
    }
}

